def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    # The repeated non-background color on the boundary forms two opposite ports.
    edge_counts = Counter()
    for c in range(w):
        edge_counts[grid[0][c]] += 1
        edge_counts[grid[h - 1][c]] += 1
    for r in range(h):
        edge_counts[grid[r][0]] += 1
        edge_counts[grid[r][w - 1]] += 1
    port = max((v for v in edge_counts if v != background),
               key=lambda v: edge_counts[v])

    lr_count = sum(grid[r][c] == port for r in range(h) for c in (0, w - 1))
    tb_count = sum(grid[r][c] == port for r in (0, h - 1) for c in range(w))
    horizontal_rays = lr_count >= tb_count

    # Find contiguous port segments on the two relevant opposite borders.
    if horizontal_rays:
        sides = [[r for r in range(h) if grid[r][c] == port]
                 for c in (0, w - 1)]
        axis_len = h
    else:
        sides = [[c for c in range(w) if grid[r][c] == port]
                 for r in (0, h - 1)]
        axis_len = w

    def runs(indices):
        if not indices:
            return []
        result = []
        start = prev = indices[0]
        for x in indices[1:]:
            if x != prev + 1:
                result.append((start, prev))
                start = x
            prev = x
        result.append((start, prev))
        return result

    side_runs = [runs(s) for s in sides]
    # Foreground markers are the non-background, non-port interior color.
    marker_counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                            if grid[r][c] not in (background, port))
    if not marker_counts:
        return out
    marker = marker_counts.most_common(1)[0][0]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]

    # Each marker selects its offset within the boundary segment it aligns with;
    # transfer that offset to both opposite ports.
    offsets = set()
    for r, c in markers:
        q = r if horizontal_rays else c
        for run_list in side_runs:
            for a, b in run_list:
                if a <= q <= b:
                    offsets.add(q - a)
                    break
            if any(a <= q <= b for a, b in run_list):
                break

    for (side_index, run_list) in enumerate(side_runs):
        for a, b in run_list:
            for offset in offsets:
                q = a + offset
                if q > b:
