        vals = (grid[0] if edge == 'top' else grid[-1] if edge == 'bottom'
                else [grid[r][0] for r in range(h)] if edge == 'left'
                else [grid[r][-1] for r in range(h)])
        ans=[]; i=0
        while i < len(vals):
            if vals[i] == bg:
                i += 1; continue
            color=vals[i]; j=i+1
            while j < len(vals) and vals[j] == color: j += 1
            ans.append((color,i,j-1)); i=j
        return ans

    candidates=[]
